inline const uint8_t* verticalStateBitmap(vertical_state::State state) {
  switch (state) {
    case vertical_state::State::CLIMBING:
      return VERTICAL_STATE_BITMAP_CLIMBING;
    case vertical_state::State::DESCENDING:
      return VERTICAL_STATE_BITMAP_DESCENDING;
    case vertical_state::State::LEVEL:
    default:
      return VERTICAL_STATE_BITMAP_LEVEL;
  }
}
